function pageFromPath(){let path=window.location.pathname;if(basePath&&path.startsWith(basePath))path=path.slice(basePath.length)||'/';path=path.replace(/\/$/,'')||'/';if(path==='/')return 'Home';if(path==='/matches')return 'Find Matches';if(path==='/teams')return 'Teams';if(path==='/players'||path.startsWith('/players/'))return 'Players';if(path==='/tournaments')return 'Tournaments';if(path==='/live')return 'Live Scores';if(path==='/news'||path.startsWith('/news/'))return 'News';if(path==='/dashboard')return 'Dashboard';return 'Not Found'}
